import{At as e,Et as t,dt as n,ft as r,lt as i,n as a,ot as o,ut as s}from"./chunks/framework.8UxoGp64.js";var c=JSON.parse(`{"title":"SankeyChart 桑基图","description":"","frontmatter":{},"headers":[],"relativePath":"components/sankey-chart.md","filePath":"components/sankey-chart.md","lastUpdated":1791177194000}`),l={name:`components/sankey-chart.md`},u={id:`sankeychart-桑基图`,tabindex:`-1`};function d(a,c,l,d,f,p){let m=e(`Badge`),h=e(`XhDemo`);return t(),i(`div`,null,[o(`h1`,u,[c[0]||=n(`SankeyChart 桑基图 `,-1),r(m,{type:`tip`,text:`new`}),c[1]||=n(),c[2]||=o(`a`,{class:`header-anchor`,href:`#sankeychart-桑基图`,"aria-label":`Permalink to “SankeyChart 桑基图”`},`​`,-1)]),c[3]||=s(`<p>看流量从哪里来、到哪里去、在哪里流失。节点分列排开，流带的宽度与流量成正比。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/sankey-chart" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/sankey-chart.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/sankey-chart" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/sankey-chart" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/sankey-chart.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h2><p>节点分列排开，流带的宽度与流量成正比；节点按分组着色，悬停节点时相连的流带换成它的颜色</p>`,4),r(h,{src:`sankey-chart/01-basic`}),c[4]||=s(`<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to “组件结构”">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;sankey-chart&quot;</code>：<strong><code>root</code></strong> · <code>caption</code> · <code>legend</code> · <code>legend-item</code> · <code>legend-swatch</code> · <code>legend-label</code> · <strong><code>viewport</code></strong> · <strong><code>plot</code></strong> · <code>defs</code> · <code>gradient</code> · <code>gradient-stop</code> · <code>link</code> · <code>node</code> · <code>node-label</code> · <code>focus-ring</code> · <code>tooltip</code> · <code>tooltip-header</code> · <code>tooltip-row</code> · <code>tooltip-swatch</code> · <code>tooltip-value</code> · <code>tooltip-name</code> · <code>empty</code> · <code>summary</code> · <code>table-region</code> · <code>table</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><h3 id="自上而下" tabindex="-1">自上而下 <a class="header-anchor" href="#自上而下" aria-label="Permalink to “自上而下”">​</a></h3><p>orientation=&quot;vertical&quot; 让流向朝下：页面是竖长的阅读顺序、或者列里的名字很长时用它</p>`,6),r(h,{src:`sankey-chart/02-vertical`}),c[5]||=o(`h3`,{id:`流带随来源着色`,tabindex:`-1`},[n(`流带随来源着色 `),o(`a`,{class:`header-anchor`,href:`#流带随来源着色`,"aria-label":`Permalink to “流带随来源着色”`},`​`)],-1),c[6]||=o(`p`,null,`linkColor="source" 让每条流带取源节点的颜色：读者要一路跟着某个来源看它流向哪里时用它`,-1),r(h,{src:`sankey-chart/03-link-source`}),c[7]||=o(`h3`,{id:`渐变流带`,tabindex:`-1`},[n(`渐变流带 `),o(`a`,{class:`header-anchor`,href:`#渐变流带`,"aria-label":`Permalink to “渐变流带”`},`​`)],-1),c[8]||=o(`p`,null,`linkColor="gradient" 让流带从源节点的颜色渐变到目标节点的颜色，两端的分组一眼看得出`,-1),r(h,{src:`sankey-chart/04-gradient`}),c[9]||=o(`h3`,{id:`只写流带`,tabindex:`-1`},[n(`只写流带 `),o(`a`,{class:`header-anchor`,href:`#只写流带`,"aria-label":`Permalink to “只写流带”`},`​`)],-1),c[10]||=o(`p`,null,`不写 nodes 时节点按流带里出现的先后推断，名字就是身份，全部用同一个颜色`,-1),r(h,{src:`sankey-chart/05-links-only`}),c[11]||=s(`<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to “设计指引”">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h3><ul><li>量在几个阶段之间分流、汇合：用户从哪些渠道进来、经过哪些页面、最后下单还是离开；预算从来源分到部门再分到项目；能源从产出到消耗。</li><li>读者关心的是「大头流向哪里」与「在哪一步流失」，而不是每条流带的精确数字。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to “何时不用”">​</a></h3><ul><li>只有一条线性的流程、每步只会留下或离开：用<a href="./funnel-chart">漏斗图</a>，逐级转化率读得更清楚。</li><li>流向成环（回流、循环引用）：桑基图只画有向无环的流，成环会报错；改用关系图。</li><li>要比较几个相近的流量：宽度差一点很难看出来，改用条形图或表格。</li><li>节点多到每列几十个：流带交织成一片，先按类别聚合。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li>数据是流带（<code>links</code>，每条写 <code>source</code>、<code>target</code> 与 <code>value</code>）；节点（<code>nodes</code>，每个写 <code>id</code>，可选 <code>name</code> 与 <code>group</code>）缺省按流带里出现的先后推断，名字即身份。成环、自环、端点不存在或节点重复时报 <code>chart.sankey-shape</code>，流量为负时报 <code>chart.negative-share</code>，根上写 <code>data-state=&quot;error&quot;</code>。</li><li>节点的值取流入与流出里较大的那个；节点分到哪一列由 <code>nodeAlign</code> 决定：<code>justify</code>（缺省）两端对齐、没有出边的节点贴到最后一列，<code>start</code> 靠源头，<code>end</code> 靠汇点，<code>center</code> 居中。列内次序缺省由布局按相连节点的位置排，<code>nodeSort=&quot;input&quot;</code> 保持数据次序。</li><li><code>orientation</code> 取 <code>horizontal</code>（缺省，自左而右）或 <code>vertical</code>（自上而下）。节点的厚度取组件槽 <code>--xh-sankey-chart-node-width</code>，同一列相邻节点至少隔一行字。</li><li>颜色：节点按 <code>group</code> 第一次出现的先后分配分类色 1–8，没有分组时全部用色槽 1；多于 8 组时报 <code>chart.too-many-series</code>。流带缺省是半透明的中性色；<code>linkColor</code> 取 <code>source</code> / <code>target</code> 时用源或目标节点的颜色，取 <code>gradient</code> 时从源节点渐变到目标节点。</li><li>名字写在节点侧面、列间的空当里：前半程写在下游一侧，后半程写在上游一侧，放不下时截断；一列里挨得太近的名字只留前一个，其余交给提示框与数据表。</li><li>有两组及以上时显示图例，点图例项切换这一组的显隐：隐藏的节点与连着它们的流带不画，其余重新排布；悬停图例项时只留这一组。</li><li>悬停节点时连着它的流带换成它的颜色，其余淡出到 <code>--xh-chart-dim-alpha</code>；提示框写合计与流入、流出的明细（各列前 6 条，多出来的合成「其他」）。悬停流带时只留它和两端，提示框写流量与它占源节点流出、占目标节点流入的比例。细的节点沿流向放宽到最小命中尺寸 <code>--xh-chart-hit-min</code>。</li><li><code>format</code> 指定数值格式（数字格式或函数），提示框、可及名与数据表共用。</li><li>多张图接到同一个受控的 <code>activeKey</code> 上时，节点按身份、流带按「源→目标」与其他图对齐。</li><li><code>pending</code> 表示正在重新取数：保留上一帧、整体降低不透明度并在根上写 <code>aria-busy</code>。首次取数、手里还没有数据时，空态写 <code>translations.loadingText</code> 并转一个圈，取完仍没有流带才写 <code>emptyText</code>。</li><li>首次出现时流带与节点一起淡入，数据晚于挂载到达（异步取数，或 Web Components 连上之后才赋 <code>data</code>）时同样播这段入场；之后的数据变化与图例切换从当前的位置与宽度插值到新布局，离开的节点与流带淡出后才移除。<code>animated={false}</code>（Web Components 写 <code>animated=&quot;false&quot;</code>）关闭过渡；系统开了减弱动效或容器写了 <code>data-motion=&quot;reduce&quot;</code> 时几何直接到位，只保留淡入淡出。</li><li>三个适配器的作者侧写法不同，最终 DOM 一致：Vue 与 React 不写默认内容时铺开缺省结构（标题、图例、视口与绘图区、空态、提示框），提示框内容可由作用域插槽 / 函数式 children 替换；Web Components 侧作者写外壳（root、caption、legend、viewport 与其中空的 <code>&lt;svg&gt;</code> plot，可选 empty 与 tooltip），渐变、流带、节点、图例项与提示框的缺省内容由元素生成进去。</li><li>Web Components 侧的节点、流带与数值格式只走 JS property；流向、分列、列内次序、流带着色与 <code>active-key</code> 另有同名属性。宿主元素缺省是行内元素，放进 flex / grid 时要给它一个宽度。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><ul><li>为图写标题：<code>caption</code> 是图的可访问名称，也要说明流的是什么、单位是什么。</li><li>用分组给节点着色，把「在哪一步」或「属于哪一类」交给颜色，名字留给身份；分组不超过 8 个。</li><li>流带缺省用中性色：颜色留给悬停时的强调；只有流向本身要按来源区分时才用 <code>linkColor=&quot;source&quot;</code>。</li><li>需要读出准确数字时，在旁边放一张<a href="./table">表格</a>，或把 <code>api.table</code> 交给表格组件（Vue 与 React 从根的作用域插槽 / 函数式 children 取 <code>table</code>，Web Components 读元素的 <code>table</code>）。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to “反模式”">​</a></h3><ul><li>把有回流的数据硬画成桑基图：成环会报错，拆掉回流又会让读者误以为流量在减少。</li><li>同一张图里流量差几个数量级：最细的流带只剩一根线，读者看不到，改为把小流合并或单独画。</li><li>给每个节点一个颜色：颜色多到分不清，也没有表达任何分组。</li><li>用提示框作为读取数值的唯一途径：提示框对读屏隐藏，数值要能从可及名、摘要或数据表读到。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to “API 参考”">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to “产物”">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-sankey-chart&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSankeyChartCaption</code> <code>XhSankeyChartEmpty</code> <code>XhSankeyChartLegend</code> <code>XhSankeyChartPlot</code> <code>XhSankeyChartRoot</code> <code>XhSankeyChartTooltip</code> <code>XhSankeyChartViewport</code></td></tr><tr><td>组合式函数</td><td><code>useSankeyChart</code></td></tr><tr><td>状态机</td><td><code>sankeyChartMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/sankey-chart.css</code></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to “事件”">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hidden-series-change</code></td><td><code>ChartHiddenSeriesChangeDetails</code></td><td>图例切换显隐；detail 为 <code>{ hiddenSeries: string[] }</code></td></tr><tr><td><code>active-key-change</code></td><td><code>ChartActiveKeyChangeDetails</code></td><td>指针或键盘换了激活的节点或流带；detail 为 <code>{ activeKey }</code>，收起时为 null</td></tr><tr><td><code>datum-active</code></td><td><code>ChartDatumDetails</code></td><td>悬停或聚焦到某个节点或流带；detail 为数据详情，收起时为 null</td></tr><tr><td><code>datum-press</code></td><td><code>ChartDatumDetails</code></td><td>指针点击、Enter 或 Space 按在某个节点或流带上；detail 为数据详情</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to “插槽”">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSankeyChartRoot</code></td><td><code>default</code></td><td><code>SankeyChartRootSlotProps</code></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>caption</code></td><td>—</td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>tooltip</code></td><td><code>SankeyChartTooltipSlotProps</code></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>empty</code></td><td>—</td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhSankeyChartTooltip</code></td><td><code>default</code></td><td><code>SankeyChartTooltipSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to “React 适配器 props”">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSankeyChartRoot</code></td><td><code>nodes</code></td><td><code>readonly SankeyNodeDatum[]</code></td><td></td><td>节点：身份、名字与分组；缺省按流带里出现的先后推断。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>links</code></td><td><code>readonly SankeyLinkDatum[]</code></td><td></td><td>流带：源、目标与流量。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>orientation</code></td><td><code>SankeyOrientation</code></td><td></td><td>流向，缺省 horizontal。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>nodeAlign</code></td><td><code>SankeyNodeAlign</code></td><td></td><td>节点分列的方式，缺省 justify。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>linkColor</code></td><td><code>SankeyLinkColor</code></td><td></td><td>流带的颜色，缺省 neutral。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>nodeSort</code></td><td><code>SankeyNodeSort</code></td><td></td><td>列内次序，缺省 auto。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>format</code></td><td><code>NumberFormatSpec | ((value: number) =&gt; string)</code></td><td></td><td>数值格式。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td><td>隐藏的分组（受控）。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>defaultHiddenSeries</code></td><td><code>string[]</code></td><td></td><td>初始隐藏的分组（非受控）。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td><td>激活的键（受控）：与别的图联动时是节点的身份或「源→目标」。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>pending</code></td><td><code>boolean</code></td><td></td><td>数据重取中：保留上一帧、整体降低不透明度。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>animated</code></td><td><code>boolean</code></td><td></td><td>播放过渡动画，缺省 true；false 时直接画终态。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>locale</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>translations</code></td><td><code>Partial&lt;SankeyChartTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>onHiddenSeriesChange</code></td><td><code>SankeyChartProps[&#39;onHiddenSeriesChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>onActiveKeyChange</code></td><td><code>SankeyChartProps[&#39;onActiveKeyChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>onDatumActive</code></td><td><code>SankeyChartProps[&#39;onDatumActive&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>onDatumPress</code></td><td><code>SankeyChartProps[&#39;onDatumPress&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>caption</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>renderTooltip</code></td><td><code>(props: SankeyChartTooltipSlotProps) =&gt; ReactNode</code></td><td></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>empty</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhSankeyChartRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;SankeyChartRootSlotProps&gt;</code></td><td></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhSankeyChartTooltip</code></td><td><code>children</code></td><td><code>SlotChildren&lt;SankeyChartTooltipSlotProps&gt;</code></td><td></td><td>替换缺省内容；函数式 children 拿到激活的节点或流带与缺省的内容模型。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to “状态”">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>empty</code></td><td>&#39;loading&#39; | undefined</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to “connect API”">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>SankeyModel</code></td><td>管线产物：图、布局、场景与无障碍模型。</td></tr><tr><td><code>scene</code></td><td><code>Scene</code></td><td>要画的场景；尚未测量时为空场景。</td></tr><tr><td><code>overlay</code></td><td><code>SankeyOverlay</code></td><td>前景层：焦点环。</td></tr><tr><td><code>measured</code></td><td><code>boolean</code></td><td>视口尚未测量（服务端与首帧）。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>没有可画的流带。</td></tr><tr><td><code>legendItems</code></td><td><code>readonly SankeyLegendItem[]</code></td><td></td></tr><tr><td><code>gradients</code></td><td><code>readonly SankeyGradient[]</code></td><td>linkColor=&quot;gradient&quot; 时每条流带一个渐变；其余时候为空。</td></tr><tr><td><code>active</code></td><td><code>ChartDatumDetails | null</code></td><td>激活的节点或流带；没有时为 null。</td></tr><tr><td><code>tooltip</code></td><td><code>SankeyTooltipModel | null</code></td><td>提示框内容；收起时为 null。</td></tr><tr><td><code>summary</code></td><td><code>string</code></td><td></td></tr><tr><td><code>table</code></td><td><code>TableModel</code></td><td>数据表模型：每条流带一行，源、目标与流量三列。</td></tr><tr><td><code>emptyText</code></td><td><code>string</code></td><td></td></tr><tr><td><code>tableCaption</code></td><td><code>string</code></td><td></td></tr><tr><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td></tr><tr><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>toggleSeries</code></td><td><code>(id: string) =&gt; void</code></td><td>切换某个分组的显隐。</td></tr><tr><td><code>setFocusedDatum</code></td><td><code>(ref: { seriesId: string, index: number } | null) =&gt; void</code></td><td>移动键盘锚点：只改锚点，不移动 DOM 焦点，也不派发回调。</td></tr><tr><td><code>markTag</code></td><td><code>(mark: Mark) =&gt; SankeyMarkTag</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCaptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendItemProps</code></td><td><code>(item: SankeyLegendItem) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLegendSwatchProps</code></td><td><code>(item: SankeyLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendLabelProps</code></td><td><code>(item: SankeyLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPlotProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDefsProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>绘图区的第一个子节点：流带渐变定义在这里。</td></tr><tr><td><code>getGradientProps</code></td><td><code>(gradient: SankeyGradient) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGradientStopProps</code></td><td><code>(gradient: SankeyGradient, at: &#39;from&#39; | &#39;to&#39;) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMarkProps</code></td><td><code>(mark: Mark) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipRowProps</code></td><td><code>(row: SankeyTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipSwatchProps</code></td><td><code>(row: SankeyTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipValueProps</code></td><td><code>(row: SankeyTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipNameProps</code></td><td><code>(row: SankeyTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getEmptyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSummaryProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTableRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>数据表的视觉隐藏区域：块级、1px、裁掉，表格放在里面；隐藏不写在表格上，表格的高度收不住。</td></tr><tr><td><code>getTableProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to “无障碍”">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to “键盘”">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/toolbar/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>总是</td><td>绘图区只占一个 Tab 位：焦点落到锚点节点，首次为第一列最上面的节点；图例同样只占一个 Tab 位</td></tr><tr><td><code>ArrowDown</code></td><td>焦点在绘图区</td><td>同一列的下一个节点（竖排时是 ArrowRight）；已在最后一个则原地不动</td></tr><tr><td><code>ArrowUp</code></td><td>焦点在绘图区</td><td>同一列的上一个节点（竖排时是 ArrowLeft）</td></tr><tr><td><code>ArrowRight</code></td><td>焦点在绘图区</td><td>下游相邻的一列：取与当前节点流量最大的相连节点，没有相连的就取位置最近的（竖排时是 ArrowDown）</td></tr><tr><td><code>ArrowLeft</code></td><td>焦点在绘图区</td><td>上游相邻的一列，取法同上（竖排时是 ArrowUp）</td></tr><tr><td><code>Home</code></td><td>焦点在绘图区</td><td>第一列里位置最近的节点</td></tr><tr><td><code>End</code></td><td>焦点在绘图区</td><td>最后一列里位置最近的节点</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在绘图区</td><td>报告聚焦的节点（onDatumPress）</td></tr><tr><td><code>Escape</code></td><td>提示框显示着</td><td>收起提示框，焦点留在原处；按键不拦截，外层浮层的关闭仍归它自己</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>Home</code> / <code>End</code></td><td>焦点在图例</td><td>在图例项之间移动，左右键跟随文字方向的视觉次序</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在图例项</td><td>切换该分组的显隐（原生按钮行为）</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to “ARIA”">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>legend</code></td><td><code>aria-label</code></td><td>translations.legendLabel</td></tr><tr><td><code>legend</code></td><td><code>role</code></td><td>&#39;toolbar&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>aria-pressed</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>legend-swatch</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>plot</code></td><td><code>aria-describedby</code></td><td><code>summary</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-labelledby</code></td><td><code>caption</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-roledescription</code></td><td>translations.chartRoleDescription</td></tr><tr><td><code>plot</code></td><td><code>role</code></td><td>&#39;graphics-document&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>mark</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根是 <code>&lt;figure&gt;</code>，可访问名称来自 <code>caption</code>；不放标题时在根上写 <code>aria-label</code>。</li><li>绘图区是 <code>role=&quot;graphics-document&quot;</code>，<code>aria-describedby</code> 指向组件生成的摘要；每个节点是 <code>role=&quot;graphics-symbol&quot;</code>，名称取 <code>translations.datumLabel</code>（缺省「名字, 流量」），务必按本地语言改写。流带对读屏隐藏，也不占焦点：它们的数据全部在数据表里。</li><li>绘图区只占一个 Tab 位，焦点落在节点上：上下键在同一列里走，左右键沿流向跨到相邻的列，取与当前节点流量最大的相连节点，没有相连的就取位置最近的；竖排时两组键对调。Home / End 到第一列与最后一列。焦点环画在节点之外，只在键盘聚焦时出现。</li><li>节点名、流带与焦点环一律 <code>aria-hidden</code>；提示框同样 <code>aria-hidden</code>。</li><li>组件在根内生成一段摘要与一张数据表，视觉隐藏、对读屏可见：摘要写节点数、流带数、源头的流出合计与最大的一条流带（模板是 <code>translations.summary</code>）；数据表每条流带一行，源、目标与流量三列。</li><li>图例是 <code>role=&quot;toolbar&quot;</code>，每一项是 <code>&lt;button aria-pressed&gt;</code>，按下表示这一组可见；图例整体只占一个 Tab 位。</li><li>颜色不是区分分组的唯一线索：节点的名字写在图上，图例写出分组名；强制色下节点画成系统色的面与描边。</li><li>过渡只改画面：节点的名称、摘要与数据表在数据变化的那一刻就按新数据更新；收场中的节点 <code>aria-hidden</code>、不可聚焦。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to “样式参考”">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to “皮肤”">​</a></h3><p><code>@xihan-ui/styles/sankey-chart.css</code> 按 <code>[data-scope=&quot;sankey-chart&quot;][data-part=&quot;root&quot;]</code> 部件选择器书写，发布产物以挂载类 <code>.xh-scope-sankey-chart</code> 代替其中的 data-scope（特异性相同），位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>，部件选择器照常可用。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to “数据属性”">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>data-xh-chart-part</code></td><td>&#39;root&#39;</td></tr><tr><td><code>caption</code></td><td><code>data-xh-chart-part</code></td><td>&#39;caption&#39;</td></tr><tr><td><code>legend</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>legend-item</code></td><td><code>data-value</code></td><td>item.id</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-profile</code></td><td>&#39;text&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-item&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-pattern</code></td><td>String(item.slot)</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-slot</code></td><td>String(item.slot)</td></tr><tr><td><code>legend-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-swatch&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-xh-chart-part</code></td><td>&#39;viewport&#39;</td></tr><tr><td><code>plot</code></td><td><code>data-xh-chart-part</code></td><td>&#39;plot&#39;</td></tr><tr><td><code>gradient-stop</code></td><td><code>data-xh-chart-slot</code></td><td>String(at === &#39;from&#39; ? gradient.from : gradient.to)</td></tr><tr><td><code>tooltip</code></td><td><code>data-placement</code></td><td>&#39;top&#39; | &#39;bottom&#39;-&#39;right&#39; | &#39;left&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip&#39;</td></tr><tr><td><code>tooltip-header</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-header&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-row&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-pattern</code></td><td>undefined | String(row.slot)</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-slot</code></td><td>undefined | String(row.slot)</td></tr><tr><td><code>tooltip-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-swatch&#39;</td></tr><tr><td><code>tooltip-value</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-value&#39;</td></tr><tr><td><code>tooltip-name</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-name&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>empty</code></td><td><code>data-state</code></td><td>&#39;loading&#39; | undefined</td></tr><tr><td><code>empty</code></td><td><code>data-xh-chart-part</code></td><td>&#39;empty&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-xh-loading-ring</code></td><td>&#39;&#39;</td></tr><tr><td><code>mark</code></td><td><code>data-dimmed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-part</code></td><td>mark.part | undefined</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to “CSS 变量”">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-sankey-chart-empty-gap</code></td><td><code>empty</code></td><td><code>gap</code></td><td><code>state=loading</code></td><td><code>--xh-space-2</code></td><td>sankey-chart 的 empty 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>sankey-chart 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-height</code></td><td><code>viewport</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-chart-height</code></td><td>sankey-chart 的 viewport 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-legend-gap</code></td><td><code>legend</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>sankey-chart 的 legend 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-legend-swatch-radius</code></td><td><code>legend-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>sankey-chart 的 legend-swatch 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-link-alpha</code></td><td><code>link</code></td><td><code>fill-opacity</code></td><td><code>default</code></td><td><code>--xh-chart-link-alpha</code></td><td>sankey-chart 的 link 部件 fill-opacity 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-link-color</code></td><td><code>link</code></td><td><code>fill</code></td><td><code>default</code></td><td><code>--xh-chart-categorical-other</code></td><td>sankey-chart 的 link 部件 fill 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-node-radius</code></td><td><code>root</code></td><td><code>--xh-_chart-metric-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>sankey-chart 的 root 部件 --xh-_chart-metric-radius 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-node-width</code></td><td><code>root</code></td><td><code>--xh-_chart-metric-bar-max</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>sankey-chart 的 root 部件 --xh-_chart-metric-bar-max 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-series-color</code></td><td><code>gradient-stop</code><br><code>legend-swatch</code><br><code>link</code><br><code>node</code><br><code>pattern-line</code><br><code>tooltip-swatch</code></td><td><code>background</code><br><code>border</code><br><code>fill</code><br><code>stop-color</code><br><code>stroke</code></td><td><code>@media (forced-colors: active)</code><br><code>@media print</code><br><code>mark=line</code><br><code>where([data-xh-chart-patterns])</code><br><code>xh-chart-pattern</code><br><code>xh-chart-pattern=1</code><br><code>xh-chart-pattern=2</code><br><code>xh-chart-pattern=3</code><br><code>xh-chart-pattern=4</code><br><code>xh-chart-pattern=5</code><br><code>xh-chart-pattern=6</code><br><code>xh-chart-pattern=7</code><br><code>xh-chart-pattern=8</code><br><code>xh-chart-patterns</code><br><code>xh-chart-slot</code><br><code>xh-chart-slot=1</code><br><code>xh-chart-slot=2</code><br><code>xh-chart-slot=3</code><br><code>xh-chart-slot=4</code><br><code>xh-chart-slot=5</code><br><code>xh-chart-slot=6</code><br><code>xh-chart-slot=7</code><br><code>xh-chart-slot=8</code></td><td><code>--xh-chart-categorical-1</code><br><code>--xh-chart-categorical-2</code><br><code>--xh-chart-categorical-3</code><br><code>--xh-chart-categorical-4</code><br><code>--xh-chart-categorical-5</code><br><code>--xh-chart-categorical-6</code><br><code>--xh-chart-categorical-7</code><br><code>--xh-chart-categorical-8</code></td><td>sankey-chart 的 gradient-stop、legend-swatch、link、node、pattern-line、tooltip-swatch 部件 background、border、fill、stop-color、stroke 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-tooltip-gap</code></td><td><code>tooltip</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>sankey-chart 的 tooltip 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-tooltip-px</code></td><td><code>tooltip</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>sankey-chart 的 tooltip 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-tooltip-py</code></td><td><code>tooltip</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>sankey-chart 的 tooltip 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-tooltip-radius</code></td><td><code>tooltip</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-overlay</code></td><td>sankey-chart 的 tooltip 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-tooltip-row-gap</code></td><td><code>tooltip-row</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>sankey-chart 的 tooltip-row 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-tooltip-shadow</code></td><td><code>tooltip</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-material-frosted-shadow</code></td><td>sankey-chart 的 tooltip 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-sankey-chart-tooltip-swatch-radius</code></td><td><code>tooltip-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>sankey-chart 的 tooltip-swatch 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to “动效”">​</a></h3><p>动效角色：状态 · 出现（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-fade-in</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立；<code>opacity</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to “RTL”">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>绘图区不随文字方向镜像：横排时流向始终自左而右，右键始终是下游。</li><li>图例、标题与提示框的内容随文字方向排列，图例的左右键跟随视觉次序翻转。</li></ul>`,56)])}var f=a(l,[[`render`,d]]);export{c as __pageData,f as default};